$script:P4kToolSubjectWorkflowChecks = @(
    @{ Path = "能力资产/tools/依赖矩阵.md"; Pattern = 'Claude Code 实施|Codex ship|(?i:Claude Code implementation)'; Label = "Dependency matrix still defines dependency implementation/ship stages by tool names" },
    @{ Path = "操作系统/01_架构/三类行为铁律-附录.md"; Pattern = '仅允许绑定 Codex 发布闭环|Only within the Codex release workflow'; Label = "Three behavior classes appendix still assigns version-tag responsibility to a tool instead of Test and Release PM" },
    @{ Path = "操作系统/07_完整工作流/decision-checkpoint-附录.md"; Pattern = '外部工具战场|(?i:external-tool battlefield)'; Label = "decision-checkpoint appendix still uses external-tool workspace terminology" },
    @{ Path = "操作系统/02_智能体/项目PM-咪咪.md"; Pattern = '外部工具回流|给外部工具|写交接卡给 Claude Code|写交接卡给 Codex|仍现行.*Claude Code|Claude Code/Codex 该怎么跑测试|(?i:return from external tools|handoff to external tools|write a handoff to Claude Code|write a handoff to Codex|still current.*Claude Code|how Claude Code/Codex should run tests)'; Label = "Project PM playbook still names tools as handoff recipients or current responsibility authorities" },
    @{ Path = "操作系统/02_智能体/项目PM-咪咪-附录.md"; Pattern = '外部工具回流|给外部工具|写交接卡给 Claude Code|写交接卡给 Codex|仍现行.*Claude Code|Claude Code/Codex 该怎么跑测试|(?i:return from external tools|handoff to external tools|write a handoff to Claude Code|write a handoff to Codex|still current.*Claude Code|how Claude Code/Codex should run tests)'; Label = "Project PM appendix still names tools as handoff recipients or current responsibility authorities" },
