    @{ Path = "操作系统/02_智能体/技术PM-修复决策者-附录.md"; Pattern = '路由外部工具|手术 = Claude Code|写交接卡给 Claude Code|受众 = Claude Code|→ Claude Code（外部）|Claude Code 按|Claude Code 实施规范|(?i:route to external tools|surgery = Claude Code|write a handoff to Claude Code|audience = Claude Code|→ Claude Code \(external\)|Claude Code follows|Claude Code implementation standards)'; Label = "Technical PM appendix still names tools as implementers or audiences" },
    @{ Path = "操作系统/02_智能体/共享技能/INDEX.md"; Pattern = 'Codex 闭环前|Claude Code 完成代码后|(?i:before Codex release completion|after Claude Code finishes the code)'; Label = "Shared-skills index still triggers by tool stage" },
    @{ Path = "操作系统/02_智能体/共享技能/真机smoke清单.md"; Pattern = 'Codex 闭环前|Claude Code 完成代码后|HEAD hash 与 Codex 报告一致|(?i:before Codex release completion|after Claude Code finishes the code|HEAD matches the Codex report)'; Label = "Physical-device smoke checklist still triggers by tool stage or requires a Codex report" },
    @{ Path = "操作系统/02_智能体/共享技能/mount-stale防御.md"; Pattern = 'Codex push 后起手|Codex 报告 push 成功|HEAD hash 与 Codex 报告一致|(?i:start after Codex pushes|Codex reports a successful push|HEAD matches the Codex report)'; Label = "Mount-stale defense still requires Codex as the report author" },
    @{ Path = "操作系统/02_智能体/共享技能/PM自纠-trigger.md"; Pattern = '状态\.md 末尾 PM 切换轨迹加一行|(?i:append a PM transition row directly to the end of 状态\.md)'; Label = "PM self-correction shared skill still lets any PM write status history directly" },
    @{ Path = "操作系统/02_智能体/开发PM-实施者.md"; Pattern = '__CZXT_APP_REPO_DIR_REGEX__/src/__tests__/\*\.test\.js'; Label = "Development PM test-path allowlist remains too narrow" },
    @{ Path = "操作系统/02_智能体/项目PM-咪咪.md"; Pattern = '切产品 PM 写 PRD，再派开发 PM|(?i:switch to Product PM to write a PRD, then dispatch Development PM)'; Label = "Project PM playbook still forces bug fixes/existing implementation items through Product PM" },
    @{ Path = "操作系统/02_智能体/README.md"; Pattern = '按角色边界白名单动手 → 状态\.md 留痕|(?i:follow the role allowlist → record in 状态\.md)'; Label = "Agents README omits the writer responsible for status records" }
